package com.dermalog.android.embeddedbiometrics;
public class DEBCaptureInfo { private Object real; public DEBCaptureInfo(){} DEBCaptureInfo(Object r){real=r;} public boolean isTouch(){return bool("isTouch");} public boolean isDetect(){return bool("isDetect");} public boolean isTimeout(){return bool("isTimeout");} public boolean isCancelled(){return bool("isCancelled");} public int getFakeScore(){try{return ((Number)real.getClass().getMethod("getFakeScore").invoke(real)).intValue();}catch(Exception e){throw new IllegalStateException(e);}} private boolean bool(String n){try{return (Boolean)real.getClass().getMethod(n).invoke(real);}catch(Exception e){throw new IllegalStateException(e);}} Object real(){return real;} void bind(Object r){real=r;} }
